class _StringsExercisesEn {
	_StringsExercisesEn._(this._root);

	final Translations _root; // ignore: unused_field

	// Translations
	String get name_arnold_press => 'Arnold Press';
	String get desc_arnold_press => '1. Hold dumbbells at shoulder height with palms facing you.\n2. Exhale and press the dumbbells overhead. While pressing, smoothly rotate your wrists so your palms face forward at the top.\n3. Inhale, lower the dumbbells, and reverse the rotation back to the starting position.';
	String get name_australian_pull_up => 'Australian Pull-Up';
	String get desc_australian_pull_up => '1. Grip a low bar and position your body in a straight line from heels to head (like a reverse plank).\n2. Exhale, pull your shoulder blades back, and row your chest up to touch the bar.\n3. Squeeze at the top for 1 second, then inhale and slowly lower yourself until arms are fully extended.';
	String get name_barbell_curl => 'Barbell Bicep Curl';
	String get desc_barbell_curl => '1. Keep your back straight, chest up, and elbows pinned to your sides.\n2. Exhale, squeeze your biceps, and curl the barbell in an arc toward your chest/chin.\n3. Inhale and slowly lower the bar back to the starting position to fully stretch the biceps.';
	String get name_barbell_row => 'Barbell Row';
	String get desc_barbell_row => '1. Bend over while keeping your back naturally straight. Brace your core and look slightly down.\n2. Exhale, retract your shoulder blades, and pull the bar toward your belly button.\n3. Keep your elbows relatively close to your body. Squeeze at the top.\n4. Inhale and lower the bar slowly until your arms are fully extended.';
	String get name_barbell_squat => 'Barbell Squat';
	String get desc_barbell_squat => '1. Rest the bar on your upper back. Take a deep breath into your belly to create intra-abdominal pressure (bracing).\n2. Push your hips back and bend your knees to squat down. Go as deep as your mobility allows while keeping a straight spine.\n3. Drive hard through the floor, exhale forcefully, and stand back up.';
	String get name_bench_dips => 'Bench Dips';
	String get desc_bench_dips => '1. Place your hands on the edge of a bench and slide your hips off. Keep your arms straight.\n2. Inhale and slowly bend your elbows to lower your body until your upper arms are parallel to the floor.\n3. Exhale and push through your palms using your triceps to return to the start.';
	String get name_bench_press => 'Barbell Bench Press';
	String get desc_bench_press => '1. Unrack the barbell and hold it directly over your mid-chest.\n2. Inhale and lower the bar under control until it lightly touches your mid-chest. Do not bounce the bar.\n3. Pause briefly, then exhale, drive your feet into the floor, and press the bar back up in a slight arc toward your head.';
	String get name_bicycle_crunches => 'Bicycle Crunches';
	String get desc_bicycle_crunches => '1. Lie flat with hands behind your head and legs elevated.\n2. Exhale, extend your right leg out straight, and twist your torso to bring your right elbow toward your left knee.\n3. Inhale through the center, then exhale and switch sides in a continuous pedaling motion.';
	String get name_bulgarian_split_squat => 'Bulgarian Split Squat';
	String get desc_bulgarian_split_squat => '1. Rest your rear foot on a bench. Keep your torso upright.\n2. Inhale and slowly drop your hips by bending both knees until your front thigh is parallel to the floor (rear knee almost touching the ground).\n3. Exhale and drive through your front heel to push back up.';
	String get name_burpees => 'Burpees';
	String get desc_burpees => '1. Drop into a squat position and place your hands on the floor.\n2. Jump both feet back into a high plank position.\n3. Perform one push-up (optional).\n4. Jump your feet back into the squat, then explosively jump vertically with your hands reaching overhead.';
	String get name_cable_crossover => 'Cable Crossover';
	String get desc_cable_crossover => '1. Stand between high pulleys. Open your arms with a slight, locked bend in your elbows.\n2. Exhale and pull the handles together, crossing them over each other in front of your chest.\n3. Squeeze your chest hard for 1 second, then inhale and slowly open your arms.';
	String get name_cable_crunch => 'Cable Crunch';
	String get desc_cable_crunch => '1. Kneel facing the cable machine, holding the rope attachment behind your neck. Keep your hips locked.\n2. Exhale and crunch downward by flexing your spine, driving your elbows toward your thighs.\n3. Squeeze your abs for 1 second at the bottom.\n4. Inhale and slowly release the weight back up.';
	String get name_cable_kickback => 'Cable Glute Kickback';
	String get desc_cable_kickback => '1. Attach the ankle strap and hold onto the machine for balance. Brace your core.\n2. Exhale and squeeze your glutes to kick the working leg back and up in an arc.\n3. Hold the peak contraction for 1 second.\n4. Inhale and control the weight as you bring your leg back.';
	String get name_cable_lateral_raise => 'Cable Lateral Raise';
	String get desc_cable_lateral_raise => '1. Stand next to a low pulley and grab the D-handle with your outside hand.\n2. With a slight bend in your elbow, exhale and raise your arm out to the side until it\'s parallel to the floor.\n3. Hold for a brief second, then inhale and lower slowly.';
	String get name_chest_dips => 'Chest Dips';
	String get desc_chest_dips => '1. On parallel bars, lean your torso forward about 30 degrees to target the chest.\n2. Inhale and lower your body until your shoulders drop below your elbows (feel the stretch in your lower chest).\n3. Exhale and push through your palms to return to the top.';
	String get name_chest_supported_row => 'Chest-Supported Row';
	String get desc_chest_supported_row => '1. Lie face down on a 45-degree incline bench with your chest supported. Let dumbbells hang straight down.\n2. Exhale, pull your elbows up to the ceiling, and squeeze your shoulder blades.\n3. Inhale and slowly lower the dumbbells to stretch your back.';
	String get name_chin_up => 'Chin-Up';
	String get desc_chin_up => '1. Grab the bar with an underhand (supinated) grip. Hang with arms fully extended.\n2. Exhale, engage your lats and biceps, and pull your body up until your chin clears the bar.\n3. Inhale and lower yourself under control back to a dead hang.';
	String get name_close_grip_pulldown => 'Close-Grip Lat Pulldown';
	String get desc_close_grip_pulldown => '1. Grab the V-bar attachment and slightly puff your chest out.\n2. Exhale and pull the bar down toward your mid-chest. Keep your elbows tucked close to your sides.\n3. Squeeze your lats at the bottom, then inhale and slowly let the bar back up to get a deep stretch.';
	String get name_crunch => 'Crunch';
	String get desc_crunch => '1. Lie on your back with knees bent. Inhale and engage your core.\n2. Slowly curl your head, neck, and upper back off the floor. Keep your lower back pressed into the mat.\n3. Hold the contraction for 1 second and exhale sharply. Inhale as you lower back down.';
	String get name_crunch_machine => 'Machine Crunch';
	String get desc_crunch_machine => '1. Lock yourself into the ab crunch machine. Inhale deeply.\n2. Exhale and crunch your torso forward, contracting your abs hard.\n3. Hold the bottom position for 1 second, then inhale and slowly return to an upright position.';
	String get name_deadlift => 'Barbell Deadlift';
	String get desc_deadlift => '1. Stand with shins close to the bar. Hinge down, grip the bar, puff your chest out, and engage your lats.\n2. Take a deep breath (brace). Drive your legs into the floor and pull your torso up simultaneously.\n3. Keep the bar dragging up your shins and thighs. Lock out your hips and squeeze your glutes at the top. Exhale.\n4. Hinge your hips back first to lower the bar to the floor.';
	String get name_decline_bench_press => 'Decline Barbell Bench Press';
	String get desc_decline_bench_press => '1. Lie on a decline bench. Unrack the bar and hold it straight over your lower chest.\n2. Inhale and slowly lower the bar until it lightly touches your lower chest.\n3. Exhale and press the bar back up to the starting position.';
	String get name_decline_push_up => 'Decline Push-Up';
	String get desc_decline_push_up => '1. Place your feet on an elevated box or bench so your body forms a downward slope.\n2. Inhale and lower your chest toward the floor, keeping your elbows tucked at a 45-degree angle.\n3. Exhale and push back up to fully extended arms.';
	String get name_diamond_push_up => 'Diamond Push-Up';
	String get desc_diamond_push_up => '1. Form a diamond shape with your thumbs and index fingers placed directly under your chest.\n2. Inhale, lower your body until your chest nearly touches your hands. Keep your elbows tucked tight to your ribs.\n3. Exhale and forcefully push back up using your triceps.';
	String get name_dumbbell_bench_press => 'Dumbbell Bench Press';
	String get desc_dumbbell_bench_press => '1. Lie flat on a bench, pressing dumbbells straight up over your chest.\n2. Inhale and lower the dumbbells to the sides of your chest. Flare your elbows out at roughly a 45 to 60-degree angle.\n3. Get a deep stretch, then exhale and press the weights back up.';
	String get name_dumbbell_curl => 'Dumbbell Curl';
	String get desc_dumbbell_curl => '1. Keep your upper arms locked in place against your sides.\n2. Exhale and curl the dumbbells up toward your shoulders.\n3. Squeeze your biceps hard at the top, then inhale and lower under control.';
	String get name_dumbbell_deadlift => 'Dumbbell Deadlift';
	String get desc_dumbbell_deadlift => '1. Hold dumbbells by your sides. Inhale, brace your core, hinge your hips back, and bend your knees to lower the weights.\n2. Drive your feet into the ground to pull the weights back up.\n3. Lock your hips and squeeze your glutes at the top. Exhale.';
	String get name_dumbbell_fly => 'Dumbbell Fly';
	String get desc_dumbbell_fly => '1. Lie on a bench, pressing dumbbells straight up. Keep a slight bend in your elbows.\n2. Inhale and lower your arms out to the sides in a wide arc until you feel a deep stretch in your chest.\n3. Exhale and hug the weights back to the top following the same arc.';
	String get name_dumbbell_lateral_raise => 'Dumbbell Lateral Raise';
	String get desc_dumbbell_lateral_raise => '1. Stand with a slight bend in your elbows.\n2. Exhale and raise the dumbbells out to the sides (like pouring water from a pitcher) until your arms are parallel to the floor.\n3. Inhale and lower the weights back down slowly without losing tension.';
	String get name_dumbbell_lunges => 'Dumbbell Lunge';
	String get desc_dumbbell_lunges => '1. Hold dumbbells by your sides. Inhale and take a step forward.\n2. Drop your hips straight down until both knees form a 90-degree angle.\n3. Exhale and push off your front foot to return to the starting position.';
	String get name_dumbbell_rdl => 'Dumbbell Romanian Deadlift';
	String get desc_dumbbell_rdl => '1. Stand tall holding dumbbells in front of your thighs. Keep a slight bend in your knees.\n2. Inhale, push your hips straight back, and glide the weights down your legs until you feel a deep hamstring stretch.\n3. Exhale, squeeze your glutes, and push your hips forward to stand back up.';
	String get name_dumbbell_reverse_fly => 'Dumbbell Reverse Fly';
	String get desc_dumbbell_reverse_fly => '1. Bend over so your torso is almost parallel to the floor. Keep a slight bend in your elbows.\n2. Exhale and raise the dumbbells out to your sides like spreading wings.\n3. Squeeze your rear delts at the top, then inhale and lower slowly.';
	String get name_dumbbell_row => 'Dumbbell Row';
	String get desc_dumbbell_row => '1. Bend over keeping your back straight. Let the dumbbells hang down.\n2. Exhale and pull the dumbbells up toward your hips, driving your elbows to the ceiling.\n3. Squeeze your shoulder blades together at the top. Inhale and lower slowly.';
	String get name_dumbbell_shoulder_press => 'Dumbbell Shoulder Press';
	String get desc_dumbbell_shoulder_press => '1. Sit with chest up, holding dumbbells at shoulder level. Exhale and press them overhead.\n2. Bring the weights close together at the top without clanking them.\n3. Inhale and slowly lower them back down to ear/shoulder level.';
	String get name_dumbbell_shrugs => 'Dumbbell Shrug';
	String get desc_dumbbell_shrugs => '1. Stand tall with dumbbells hanging naturally by your sides.\n2. Exhale and shrug your shoulders straight up toward your ears.\n3. Hold the top contraction for 1 second.\n4. Inhale and lower your shoulders all the way down to stretch your traps.';
	String get name_face_pull => 'Face Pull';
	String get desc_face_pull => '1. Attach a rope to a high pulley. Pull the rope toward your forehead.\n2. As you pull, pull the handles apart and rotate your wrists up, driving your elbows back past your ears.\n3. Squeeze your shoulder blades for 1 second. Inhale and slowly return.';
	String get name_glute_bridge => 'Glute Bridge';
	String get desc_glute_bridge => '1. Lie on your back with knees bent. Inhale and brace your core.\n2. Exhale, drive through your heels, and squeeze your glutes to push your hips up until your body forms a straight line.\n3. Hold for 1-2 seconds at the top. Inhale and slowly lower your hips.';
	String get name_goblet_squat => 'Goblet Squat';
	String get desc_goblet_squat => '1. Hold a dumbbell vertically against your chest. Inhale and brace your core.\n2. Push your hips back and squat down, letting your elbows drop between your knees.\n3. Exhale, drive through your heels, and stand back up.';
	String get name_hack_squat => 'Hack Squat';
	String get desc_hack_squat => '1. Position your back flat against the Hack Squat pad. Inhale and bend your knees to lower the sled.\n2. Descend until your thighs are parallel to the footplate.\n3. Exhale and drive forcefully through your heels to push the sled back up.';
	String get name_hammer_curl => 'Hammer Curl';
	String get desc_hammer_curl => '1. Hold dumbbells with a neutral grip (palms facing each other). Keep upper arms fixed to your sides.\n2. Exhale and curl the weights up toward your shoulders, maintaining the neutral grip.\n3. Inhale and slowly lower the weights down.';
	String get name_hanging_leg_raise => 'Hanging Leg Raise';
	String get desc_hanging_leg_raise => '1. Hang from a pull-up bar. Brace your core tightly.\n2. Exhale and raise your legs straight in front of you until they are parallel to the floor (or higher).\n3. Hold for 1 second, then inhale and lower them with control.';
	String get name_high_knees => 'High Knees';
	String get desc_high_knees => '1. Run in place, driving one knee up to hip level at a time.\n2. Alternate your legs as fast as possible.\n3. Pump your arms rhythmically, keeping your chest up and core engaged.';
	String get name_hip_abduction => 'Hip Abduction Machine';
	String get desc_hip_abduction => '1. Sit in the outer thigh machine with your legs closed against the pads.\n2. Exhale and push your knees outward as far as possible using your glutes.\n3. Hold the squeeze for 1 second. Inhale and slowly bring your legs back together.';
	String get name_hip_adduction => 'Hip Adduction Machine';
	String get desc_hip_adduction => '1. Sit in the inner thigh machine with your legs spread open against the pads.\n2. Exhale and squeeze your thighs together to close the pads.\n3. Hold for 1 second. Inhale and slowly let your legs open under control.';
	String get name_hip_thrust => 'Barbell Hip Thrust';
	String get desc_hip_thrust => '1. Rest your upper back on a bench with the barbell across your hips. Position your feet so your shins are vertical at the top of the movement.\n2. Inhale, brace your core, and tuck your chin slightly.\n3. Exhale, drive through your heels, and squeeze your glutes to thrust the bar up until your thighs and torso are parallel to the floor.\n4. Hold the top for 1-2 seconds, then slowly lower.';
	String get name_hyperextensions => 'Back Extension';
	String get desc_hyperextensions => '1. Lock yourself into a back extension bench. Inhale and bend forward at the hips until your torso is vertical to the floor.\n2. Exhale and use your lower back and glutes to pull your torso up until it forms a straight line with your legs.\n3. Hold the top for 1 second, then inhale and slowly lower back down.';
	String get name_incline_barbell_press => 'Incline Barbell Bench Press';
	String get desc_incline_barbell_press => '1. Lie on an incline bench (30-45 degrees). Unrack the bar and hold it over your upper chest.\n2. Inhale and lower the bar under control until it lightly touches your upper chest/collarbone.\n3. Exhale and press the bar straight back up to the starting position.';
	String get name_incline_dumbbell_fly => 'Incline Dumbbell Fly';
	String get desc_incline_dumbbell_fly => '1. Lie on an incline bench, pressing dumbbells straight up. Keep a slight bend in your elbows.\n2. Inhale and open your arms out to the sides until you feel a deep stretch in your upper chest.\n3. Exhale and hug the weights back to the top following the same path.';
	String get name_incline_dumbbell_press => 'Incline Dumbbell Press';
	String get desc_incline_dumbbell_press => '1. Lie on an incline bench and press dumbbells up over your upper chest.\n2. Inhale and lower the dumbbells to the sides. Flare your elbows out at a 45-degree angle.\n3. Exhale, squeeze your upper chest, and press the weights back up, bringing them close together at the top.';
	String get name_incline_push_up => 'Incline Push-Up';
	String get desc_incline_push_up => '1. Place your hands on an elevated box or bench. Keep your body in a straight line.\n2. Inhale and lower your chest toward the box, keeping your elbows tucked at a 45-degree angle.\n3. Exhale and forcefully push back up to straight arms.';
	String get name_indoor_cycling => 'Indoor Cycling';
	String get desc_indoor_cycling => '1. Start pedaling at a moderate pace to warm up.\n2. Keep your core slightly engaged to stabilize your upper body and maintain a smooth, circular pedal stroke.\n3. Adjust the resistance and speed based on your workout protocol.';
	String get name_jump_rope => 'Jump Rope';
	String get desc_jump_rope => '1. Use your wrists to swing the rope over your head.\n2. Hop lightly on the balls of your feet just enough to clear the rope.\n3. Maintain a continuous rhythm and breathe steadily.';
	String get name_jumping_jacks => 'Jumping Jacks';
	String get desc_jumping_jacks => '1. Jump up and spread your legs wider than shoulder-width apart.\n2. Simultaneously swing your arms up in an arc over your head.\n3. Jump again to return your feet together and lower your arms continuously.';
	String get name_lat_pulldown => 'Lat Pulldown';
	String get desc_lat_pulldown => '1. Sit at the machine, lean back slightly (10 degrees), and puff your chest out.\n2. Exhale and pull the bar down toward your upper chest, driving your elbows down and back.\n3. Squeeze your lats, then inhale and let the bar rise back up until your arms are fully extended.';
	String get name_leg_extension => 'Leg Extension';
	String get desc_leg_extension => '1. Sit on the machine with your back flat against the pad.\n2. Exhale and use your quads to extend your legs fully straight.\n3. Squeeze your quads for 1-2 seconds at the top, then inhale and lower the weight slowly.';
	String get name_leg_press => 'Leg Press';
	String get desc_leg_press => '1. Sit in the leg press machine and place your feet on the sled. Inhale and slowly bend your knees to lower the weight toward your chest.\n2. Lower until your knees are at a 90-degree angle.\n3. Exhale and drive through your heels to push the sled back to the starting position.';
	String get name_low_to_high_fly => 'High-to-Low Cable Fly';
	String get desc_low_to_high_fly => '1. Stand between high pulleys. Open your arms with a slight bend in your elbows.\n2. Exhale and pull the handles down and across your body toward your hips.\n3. Squeeze your chest for 1 second at the bottom, then inhale and slowly open your arms.';
	String get name_lying_leg_curl => 'Lying Leg Curl';
	String get desc_lying_leg_curl => '1. Lie face down on the machine, keeping your hips pressed firmly into the pad.\n2. Exhale and curl the pad up toward your glutes as far as possible using your hamstrings.\n3. Hold the peak contraction for 1 second. Inhale and lower the weight slowly without letting the plates touch.';
	String get name_lying_leg_raise => 'Lying Leg Raise';
	String get desc_lying_leg_raise => '1. Lie flat on your back, pressing your lower back firmly into the floor.\n2. Exhale and raise both legs straight up until they are perpendicular to the ceiling.\n3. Inhale and slowly lower them until they are a few inches above the floor, then repeat.';
	String get name_machine_chest_press => 'Machine Chest Press';
	String get desc_machine_chest_press => '1. Sit in the machine and grip the handles firmly. Inhale deeply.\n2. Exhale and press the handles forward until your arms are nearly fully extended.\n3. Inhale and slowly let the handles return to the starting position, feeling the stretch in your chest.';
	String get name_mountain_climbers => 'Mountain Climbers';
	String get desc_mountain_climbers => '1. Start in a high plank push-up position.\n2. Quickly drive your right knee toward your chest, return it, and immediately drive your left knee up.\n3. Keep your core tight and hips stable as you alternate legs quickly.';
	String get name_one_arm_row => 'Single Arm Dumbbell Row';
	String get desc_one_arm_row => '1. Support one knee and one hand on a bench. Hold a dumbbell with your free hand.\n2. Exhale and pull the dumbbell up to your side, driving your elbow high and back.\n3. Squeeze your back at the top. Inhale and lower the weight to fully stretch the shoulder blade.';
	String get name_overhead_cable_triceps => 'Overhead Cable Triceps Extension';
	String get desc_overhead_cable_triceps => '1. Attach a rope to a low pulley of a cable machine. Stand facing away from the machine, grasp the rope with both hands, and pull it overhead so it rests behind your neck, with elbows pointing up.\n2. Exhale and extend both arms straight overhead, keeping your elbows locked close to your head.\n3. Inhale and slowly lower the rope back to the starting position behind your neck in a controlled manner.';
	String get name_overhead_press => 'Overhead Press';
	String get desc_overhead_press => '1. Take a deep breath, brace your core, and squeeze your glutes.\n2. Exhale and press the bar straight up. As the bar clears your face, slightly push your head forward to lock out the bar directly over your mid-foot.\n3. Inhale and lower the bar back to the front rack position under control.';
	String get name_overhead_triceps_extension => 'Overhead Triceps Extension';
	String get desc_overhead_triceps_extension => '1. Hold one dumbbell straight overhead with both hands. Keep your upper arms pinned near your ears.\n2. Inhale and bend your elbows to lower the weight behind your head until your triceps stretch.\n3. Exhale and extend your elbows to push the weight back to the top.';
	String get name_pec_deck_fly => 'Pec Deck Fly';
	String get desc_pec_deck_fly => '1. Sit in the Pec Deck machine with arms spread wide. Inhale to stretch the chest.\n2. Exhale and squeeze your arms together in front of your chest.\n3. Hold the contraction for 1 second, then inhale and slowly let the arms open back up.';
	String get name_pike_push_up => 'Pike Push-Up';
	String get desc_pike_push_up => '1. Get into an inverted V position with your hips high in the air.\n2. Inhale and lower the crown of your head toward the floor, forming a triangle with your hands.\n3. Exhale and push through your shoulders and triceps back to the start.';
	String get name_plank => 'Plank';
	String get desc_plank => '1. Support your body on your forearms and toes, forming a straight line from head to heels.\n2. Actively brace your core, glutes, and quads.\n3. Hold this static position while breathing steadily.';
	String get name_preacher_curl => 'Preacher Curl';
	String get desc_preacher_curl => '1. Sit at a Preacher bench, locking your upper arms firmly into the pad. Hold a barbell with an underhand grip.\n2. Exhale and curl the weight toward your chin, squeezing your biceps.\n3. Inhale and lower the weight slowly until your arms are almost fully extended.';
	String get name_pull_up => 'Pull-Up';
	String get desc_pull_up => '1. Grip the bar with an overhand (pronated) grip. Brace your core to prevent swinging.\n2. Exhale and pull yourself up by driving your elbows down to the floor.\n3. Pull until your chin clears the bar. Inhale and slowly lower yourself to a full dead hang.';
	String get name_push_up => 'Push-Up';
	String get desc_push_up => '1. Start in a high plank position. Keep your body in a perfectly straight line.\n2. Inhale and bend your elbows to lower your body until your chest is about an inch from the floor.\n3. Exhale and press through your chest and triceps to return to the starting position.';
	String get name_reverse_pec_deck => 'Reverse Pec Deck';
	String get desc_reverse_pec_deck => '1. Sit facing the machine. Grab the handles with a slight bend in your elbows.\n2. Exhale and pull your arms wide out to your sides and back.\n3. Squeeze your rear delts and shoulder blades together for 1 second. Inhale and slowly return.';
	String get name_romanian_deadlift => 'Barbell Romanian Deadlift';
	String get desc_romanian_deadlift => '1. Stand holding a barbell against your thighs with a slight knee bend. Keep your chest up.\n2. Inhale, push your hips straight back (hip hinge), and glide the bar down your legs until your hamstrings fully stretch.\n3. Exhale, squeeze your glutes, and push your hips forward to stand tall.';
	String get name_russian_twist => 'Russian Twist';
	String get desc_russian_twist => '1. Sit on the floor, lean back into a V-shape, and lift your feet off the ground.\n2. Exhale and forcefully twist your torso to the right side.\n3. Inhale as you return to the center, then exhale and twist to the left.';
	String get name_seated_cable_row_vgrip => 'Seated Cable Row (V-Grip)';
	String get desc_seated_cable_row_vgrip => '1. Sit at the machine with your feet on the platforms, knees slightly bent, and grasp the V-bar.\n2. Keep your back straight, chest up, and pull the handle toward your belly button while keeping your elbows tucked close to your body.\n3. Squeeze your mid-back at the peak contraction, then slowly return to the starting position to stretch your lats.';
	String get name_seated_cable_row_widegrip => 'Seated Cable Row (Wide Grip)';
	String get desc_seated_cable_row_widegrip => '1. Sit at the machine and grasp the wide bar with an overhand grip, hands wider than shoulder-width.\n2. Keep your chest up and pull the bar toward your lower chest/upper stomach, flaring your elbows slightly outward.\n3. Squeeze your shoulder blades together to target the upper back and rear delts, then slowly extend your arms back.';
	String get name_seated_calf_raise => 'Seated Calf Raise';
	String get desc_seated_calf_raise => '1. Sit at the machine with the pads resting on your lower thighs.\n2. Inhale and lower your heels as far as possible to stretch your calves.\n3. Exhale and drive through the balls of your feet to raise your heels as high as possible. Hold for 1 second.';
	String get name_seated_incline_curl => 'Incline Dumbbell Curl';
	String get desc_seated_incline_curl => '1. Sit on a 45-60 degree incline bench, letting your arms hang straight down behind your torso.\n2. Keep your upper arms completely still. Exhale, curl the dumbbells up to your shoulders, and turn your palms up.\n3. Inhale and slowly lower the weights down to a full stretch.';
	String get name_seated_leg_curl => 'Seated Leg Curl';
	String get desc_seated_leg_curl => '1. Sit in the machine with the ankle pad locked just above your heels.\n2. Exhale and curl your legs down under the seat as far as possible.\n3. Inhale and slowly return the pad upwards without letting the weight stack touch.';
	String get name_seated_wrist_curl => 'Seated Wrist Curl';
	String get desc_seated_wrist_curl => '1. Sit with your forearms resting on your thighs, holding a dumbbell or barbell palms up.\n2. Let the weight roll down to your fingertips to stretch the forearms. Exhale and forcefully curl your wrists upward.\n3. Inhale and slowly lower the weight back down.';
	String get name_shoulder_press_machine => 'Machine Shoulder Press';
	String get desc_shoulder_press_machine => '1. Sit in the machine and grab the handles at shoulder level.\n2. Exhale and press the handles straight up overhead without locking out your elbows.\n3. Inhale and control the handles as they lower back to the starting position.';
	String get name_single_arm_lat_pulldown => 'Single Arm Lat Pulldown';
	String get desc_single_arm_lat_pulldown => '1. Sit at a high pulley holding a D-handle with one hand. Puff your chest up.\n2. Exhale and pull your elbow straight down into your side.\n3. Squeeze your lat at the bottom for 1 second, then inhale and slowly release the cable.';
	String get name_skull_crushers => 'Skullcrusher';
	String get desc_skull_crushers => '1. Lie flat on a bench pressing a barbell up. Angle your upper arms slightly backward toward your head (15 degrees).\n2. Inhale and bend your elbows to lower the bar toward your forehead.\n3. Exhale and extend your elbows forcefully to return the bar to the top.';
	String get name_smith_machine_squat => 'Smith Machine Squat';
	String get desc_smith_machine_squat => '1. Place the Smith machine bar across your shoulders. Position your feet slightly further forward than a free-weight squat.\n2. Inhale, push your hips back, and squat down to parallel.\n3. Exhale and drive through your heels to stand back up.';
	String get name_squat => 'Bodyweight Squat';
	String get desc_squat => '1. Take a deep breath and brace your core. Hinge your hips back and bend your knees as if sitting in an invisible chair.\n2. Lower until your hip crease is below the top of your knees (if mobility allows). Keep your weight evenly distributed across your whole foot.\n3. Exhale, drive through the floor, squeeze your glutes and quads to stand back up.';
	String get name_stair_climber => 'Stair Climber';
	String get desc_stair_climber => '1. Step rhythmically onto the moving stairs.\n2. Place your entire foot on the step and push through your heels to maximally engage your glutes.';
	String get name_standing_calf_raise => 'Standing Calf Raise';
	String get desc_standing_calf_raise => '1. Stand with the balls of your feet on a raised platform. Inhale and let your heels drop to get a deep stretch.\n2. Exhale and raise your heels as high as possible. Keep your knees straight but not locked.\n3. Hold the contraction for 1-2 seconds, then lower slowly.';
	String get name_superman => 'Superman';
	String get desc_superman => '1. Lie face down on a mat with arms and legs fully extended.\n2. Squeeze your lower back and simultaneously lift your arms, chest, and legs off the floor.\n3. Hold the top position for 2-3 seconds, breathing shallowly, then lower back down.';
	String get name_t_bar_row => 'T-Bar Row';
	String get desc_t_bar_row => '1. Bend over, straddling the T-bar. Keep your back naturally straight.\n2. Exhale, pull the bar forcefully toward your chest/stomach, and squeeze your shoulder blades together.\n3. Inhale and lower the bar under control to fully stretch your back.';
	String get name_treadmill => 'Treadmill';
	String get desc_treadmill => '1. Start the belt at a slow speed before stepping on.\n2. Adjust the Speed and Incline to match your workout goals.\n3. Keep your posture upright, look forward, and pump your arms rhythmically.';
	String get name_tricep_pushdown => 'Triceps Pushdown';
	String get desc_tricep_pushdown => '1. Stand at a high cable pulley. Pin your elbows tightly against your ribs.\n2. Exhale and push the bar/rope straight down until your arms are fully locked out.\n3. Inhale and slowly let the cable pull your forearms back up without moving your elbows.';
	String get name_upright_row => 'Upright Row';
	String get desc_upright_row => '1. Hold a barbell with a narrow grip resting against your thighs.\n2. Exhale and pull the bar straight up to your chin, leading with your elbows. Your elbows must always be higher than your wrists.\n3. Hold for 1 second at the top, then inhale and lower straight down.';
	String get desc_warm_up => 'Thoroughly rotate your wrists, ankles, shoulders, hips, and knees for 5-10 minutes to lubricate the joints and raise your heart rate.';
	String get type_cardio_dist => 'Distance & Time';
	String get type_cardio_steps => 'Steps & Time';
	String get type_reps_only => 'Reps Only';
	String get type_time_only => 'Time Only';
	String get type_wt_reps => 'Weight & Reps';
}

