// Path: programs
class _StringsProgramsEn {
	_StringsProgramsEn._(this._root);

	final Translations _root; // ignore: unused_field

	// Translations
	String get cardio_gym_int_desc => 'A cardiovascular training system with continuously varying, powerful intensities. Strongly emphasizes massive calorie burn, eliminating stubborn fat, and elevating endurance to a completely new standard.';
	String get cardio_gym_int_name => 'Fat Burning Cardio & HIIT (Gym)';
	String get combo_db_adv_desc => 'Challenge every limit of endurance at home with a relentless 5-day rotating schedule. By pushing dumbbell intensity to the max, this routine drains energy and forces the body to adapt by growing bigger and stronger.';
	String get combo_db_adv_name => 'PPL & Upper/Lower - Advanced (Dumbbell)';
	String get combo_db_beg_desc => 'A hybrid dumbbell version over 3 days a week acting as a primer. Gentle and easy to execute, but still provides enough stimulus for muscles to recognize the need for change and begin a stronger rebuilding process.';
	String get combo_db_beg_name => 'PPL & Upper/Lower - Beginner (Dumbbell)';
	String get combo_db_int_desc => 'A scientifically split 5-day home routine. Maximizes dumbbell utility to deliver clear physique development while still leaving enough time for muscle groups to rest and grow.';
	String get combo_db_int_name => 'PPL & Upper/Lower - Intermediate (Dumbbell)';
	String get combo_gym_adv_desc => 'The pinnacle of workout programming with 5 of the most grueling sessions. Tailored specifically for seasoned individuals who want to force their bodies into continuous stress to achieve physical perfection.';
	String get combo_gym_adv_name => 'PPL & Upper/Lower - Advanced (Gym)';
	String get combo_gym_beg_desc => 'Creates a gentle transitional stepping stone with 3 days a week for the body to adapt before moving to the intensive 5-day hybrid routine. Helps build a solid foundation and physical readiness for harsher challenges.';
	String get combo_gym_beg_name => 'PPL & Upper/Lower - Beginner (Gym)';
	String get combo_gym_int_desc => 'The 5-day structure provides the perfect balance between muscle hypertrophy goals and maximal strength gains. Smart rotation between workout days optimizes recovery capacity and prevents overtraining.';
	String get combo_gym_int_name => 'PPL & Upper/Lower - Intermediate (Gym)';
	String get fb_bw_adv_desc => 'A journey of primal strength training through advanced calisthenics movements like pull-ups, dips, and hard-to-control variations. Requires a perfect blend of raw power, balance, and absolute core strength.';
	String get fb_bw_adv_name => 'Full Body - Advanced (Bodyweight)';
	String get fb_bw_beg_desc => 'Use your own body weight as resistance to train balance and strengthen the core. A gentle, easily accessible routine for any space, helping you build discipline without investing in complex equipment.';
	String get fb_bw_beg_name => 'Full Body - Beginner (Bodyweight)';
	String get fb_bw_int_desc => 'Increase the challenge through complex bodyweight exercise variations. This routine not only burns massive energy but also develops agility, flexibility, and spatial body control.';
	String get fb_bw_int_name => 'Full Body - Intermediate (Bodyweight)';
	String get fb_db_adv_desc => 'Exhaust the entire body using slow, controlled tempos and peak dumbbell intensity. Forces every muscle fiber to engage, delivering muscle-building and shredding results far beyond expectations.';
	String get fb_db_adv_name => 'Full Body - Advanced (Dumbbell)';
	String get fb_db_beg_desc => 'A comprehensive, time-saving home workout solution using just a pair of dumbbells. Wakes up every muscle group through fundamental movements, perfect for busy individuals wanting to maintain an active habit.';
	String get fb_db_beg_name => 'Full Body - Beginner (Dumbbell)';
	String get fb_db_int_desc => 'Elevate overall fitness by increasing volume and incorporating diverse dumbbell exercises. Ensures the entire body is trained evenly, bringing about tone, fat loss, and significant cardiovascular improvements.';
	String get fb_db_int_name => 'Full Body - Intermediate (Dumbbell)';
	String get fb_gym_adv_desc => 'Requires incredible stamina with 3 horrifyingly intense sessions per week. This routine constantly challenges both neural and full-body muscular endurance, designed to shatter the physical limits of veteran lifters.';
	String get fb_gym_adv_name => 'Full Body - Advanced (Gym)';
	String get fb_gym_beg_desc => 'Activate all major muscle groups in a single session with a frequency of 2-3 times per week. The perfect stepping stone to introduce beginners to resistance, optimizing time while mastering basic movement techniques.';
	String get fb_gym_beg_name => 'Full Body - Beginner (Gym)';
	String get fb_gym_int_desc => 'A 3-day-per-week routine inspired by professional strength athletes. Focuses heavily on heavyweight barbell exercises to fire up the central nervous system, resulting in superior foundational strength and dense muscle mass.';
	String get fb_gym_int_name => 'Full Body - Intermediate (Gym)';
	String get ppl_db_adv_desc => 'Apply advanced training techniques and push muscles to exhaustion with 6 days a week using dumbbells. Requires intense focus, maximizing free-weight efficiency to sculpt a sharp and detailed physique.';
	String get ppl_db_adv_name => 'Push Pull Legs - Advanced (Dumbbell)';
	String get ppl_db_beg_desc => 'Start your physique transformation journey at home with just 3 days a week and a pair of dumbbells. This routine offers maximum convenience, helping beginners easily access resistance training safely and effectively in their own space.';
	String get ppl_db_beg_name => 'Push Pull Legs - Beginner (Dumbbell)';
	String get ppl_db_int_desc => 'Fully exploit the potential of dumbbells with a challenging 6-day-per-week schedule. By varying movement angles and increasing sets, this routine ensures muscles continuously receive strong growth signals even when training at home.';
	String get ppl_db_int_name => 'Push Pull Legs - Intermediate (Dumbbell)';
	String get ppl_gym_adv_desc => 'Push your body past its limits with an extremely high-intensity 6-day routine. Maximizes heavy loads on compound movements and refines muscle details through isolation exercises, specifically designed to break plateaus and drive maximum muscle growth.';
	String get ppl_gym_adv_name => 'Push Pull Legs - Advanced (Gym)';
	String get ppl_gym_beg_desc => 'Ideal roadmap to get used to a 3-day-per-week training rhythm using safe fixed machines. This routine helps beginners build a solid muscular foundation, grasp proper technique, and minimize injury risk in the early stages.';
	String get ppl_gym_beg_name => 'Push Pull Legs - Beginner (Gym)';
	String get ppl_gym_int_desc => 'Elevate the challenge with a 6-day-per-week intensity flexibly combining barbells and dumbbells. Focuses on increasing overall training volume, stimulating balanced muscle growth, and visibly improving foundational strength.';
	String get ppl_gym_int_name => 'Push Pull Legs - Intermediate (Gym)';
	String get ul_db_adv_desc => 'A brutally strict dumbbell schedule requiring absolute discipline. Optimizes time under tension to create an ideal growth environment, delivering muscle-building results that rival professional gym training.';
	String get ul_db_adv_name => 'Upper Lower - Advanced (Dumbbell)';
	String get ul_db_beg_desc => 'A streamlined and highly effective 4-day home routine using dumbbells. This schedule equally divides focus between upper and lower body, helping you build a solid physical foundation without spending too much time.';
	String get ul_db_beg_name => 'Upper Lower - Beginner (Dumbbell)';
	String get ul_db_int_desc => 'Challenge muscle endurance at home with high-intensity dumbbell variations over 4 days a week. The structure is scientifically arranged to ensure continuous stimulation, visibly transforming your physique week by week.';
	String get ul_db_int_name => 'Upper Lower - Intermediate (Dumbbell)';
	String get ul_gym_adv_desc => 'Face a massive training volume and relentless progressive overload meant for seasoned lifters. This 4-day schedule optimizes neural endurance and maximally activates fast-twitch muscle fibers.';
	String get ul_gym_adv_name => 'Upper Lower - Advanced (Gym)';
	String get ul_gym_beg_desc => 'Divide the body into upper and lower halves with a 4-day-per-week rhythm. This smart structure provides optimal rest periods, helping beginners recover fully while maintaining necessary stimulation for muscle growth.';
	String get ul_gym_beg_name => 'Upper Lower - Beginner (Gym)';
	String get ul_gym_int_desc => 'Shift focus to heavy multi-joint barbell exercises across 4 days a week. This routine is the key to increasing explosive power, driving muscle size, and creating a leap in body mass.';
	String get ul_gym_int_name => 'Upper Lower - Intermediate (Gym)';
}

