// Path: programs
class _StringsProgramsVi extends _StringsProgramsEn {
	_StringsProgramsVi._(_StringsVi root) : this._root = root, super._(root);

	@override final _StringsVi _root; // ignore: unused_field

	// Translations
	@override String get cardio_gym_int_desc => 'Hệ thống bài tập rèn luyện hệ tim mạch với cường độ thay đổi liên tục và mạnh mẽ. Chú trọng đặc biệt vào khả năng đốt cháy lượng calo khổng lồ, loại bỏ mỡ thừa ngoan cố và nâng tầm sức bền thể lực lên một tiêu chuẩn hoàn toàn mới.';
	@override String get cardio_gym_int_name => 'Cardio & HIIT Đốt Mỡ (Phòng Tập)';
	@override String get combo_db_adv_desc => 'Thách thức mọi giới hạn sức chịu đựng tại nhà với lịch tập năm buổi luân phiên không ngừng nghỉ. Bằng cách đẩy cường độ tạ đơn lên mức cao nhất, giáo án này vắt kiệt năng lượng và ép buộc cơ thể phải thích nghi bằng cách phát triển to hơn và mạnh hơn.';
	@override String get combo_db_adv_name => 'Đẩy Kéo Chân & Trên Dưới - Nâng Cao (Tạ Đơn)';
	@override String get combo_db_beg_desc => 'Phiên bản kết hợp sử dụng tạ đơn trong ba ngày mỗi tuần mang tính chất khởi động. Nhẹ nhàng, dễ thực hiện nhưng vẫn đảm bảo sự kích thích đủ để cơ bắp nhận biết được sự thay đổi và bắt đầu quá trình tái tạo mạnh mẽ hơn.';
	@override String get combo_db_beg_name => 'Đẩy Kéo Chân & Trên Dưới - Cơ Bản (Tạ Đơn)';
	@override String get combo_db_int_desc => 'Lịch trình năm buổi mỗi tuần tại nhà được phân chia nhóm cơ cực kỳ khoa học và tinh tế. Tận dụng tối đa tạ đơn để mang lại hiệu quả phát triển vóc dáng rõ rệt trong khi vẫn chừa đủ thời gian để các nhóm cơ nghỉ ngơi và phát triển.';
	@override String get combo_db_int_name => 'Đẩy Kéo Chân & Trên Dưới - Trung Cấp (Tạ Đơn)';
	@override String get combo_gym_adv_desc => 'Đỉnh cao của nghệ thuật lập trình tập luyện với năm buổi cường độ gắt gao nhất. Giáo án này được thiết kế riêng cho những cá nhân đã dày dặn kinh nghiệm, muốn áp đặt cơ thể vào trạng thái căng thẳng liên tục để đạt được sự hoàn mỹ về vóc dáng.';
	@override String get combo_gym_adv_name => 'Đẩy Kéo Chân & Trên Dưới - Nâng Cao (Phòng Tập)';
	@override String get combo_gym_beg_desc => 'Tạo bước đệm chuyển tiếp nhẹ nhàng với ba ngày mỗi tuần để cơ thể dần làm quen trước khi tiến tới lịch tập kết hợp năm ngày chuyên sâu. Giúp xây dựng nền móng vững chắc và chuẩn bị thể lực cho những thử thách khắc nghiệt hơn.';
	@override String get combo_gym_beg_name => 'Đẩy Kéo Chân & Trên Dưới - Cơ Bản (Phòng Tập)';
	@override String get combo_gym_int_desc => 'Cấu trúc năm buổi mỗi tuần mang đến sự cân bằng hoàn hảo giữa mục tiêu phát triển độ lớn cơ bắp và gia tăng sức mạnh tối đa. Sự luân phiên thông minh giữa các ngày tập giúp tối ưu hóa khả năng phục hồi và ngăn ngừa tình trạng quá tải.';
	@override String get combo_gym_int_name => 'Đẩy Kéo Chân & Trên Dưới - Trung Cấp (Phòng Tập)';
	@override String get fb_bw_adv_desc => 'Hành trình rèn luyện sức mạnh nguyên thủy thông qua các động tác nâng cao như hít xà đơn, xà kép và các biến thể khó kiểm soát. Đòi hỏi sự kết hợp hoàn hảo giữa sức mạnh thuần túy, sự thăng bằng và sức mạnh hệ cơ lõi tuyệt đối.';
	@override String get fb_bw_adv_name => 'Toàn Thân - Nâng Cao (Không Tạ)';
	@override String get fb_bw_beg_desc => 'Sử dụng chính trọng lượng cơ thể làm sức cản để rèn luyện thăng bằng và củng cố sức mạnh vùng cơ lõi. Lịch trình nhẹ nhàng, dễ tiếp cận ở mọi không gian, giúp bạn hình thành thói quen kỷ luật mà không cần đầu tư bất kỳ dụng cụ phức tạp nào.';
	@override String get fb_bw_beg_name => 'Toàn Thân - Cơ Bản (Không Tạ)';
	@override String get fb_bw_int_desc => 'Đẩy mạnh mức độ thử thách thông qua các bài tập thể dục trọng lượng cơ thể biến thể phức tạp hơn. Giáo án này không chỉ đốt cháy năng lượng mạnh mẽ mà còn phát triển sự dẻo dai, linh hoạt và khả năng kiểm soát cơ thể trong không gian.';
	@override String get fb_bw_int_name => 'Toàn Thân - Trung Cấp (Không Tạ)';
	@override String get fb_db_adv_desc => 'Vắt kiệt sức lực toàn thân bằng các kỹ thuật kiểm soát nhịp độ chậm rãi và cường độ tập luyện đỉnh cao cùng tạ đơn. Giáo án ép buộc mọi sợi cơ phải tham gia vào quá trình vận động, đem lại hiệu quả tăng cơ và cắt nét vượt xa mong đợi.';
	@override String get fb_db_adv_name => 'Toàn Thân - Nâng Cao (Tạ Đơn)';
	@override String get fb_db_beg_desc => 'Giải pháp tập luyện toàn diện tại nhà cực kỳ tiết kiệm thời gian chỉ với một đôi tạ đơn. Giáo án giúp đánh thức mọi nhóm cơ trên cơ thể thông qua các chuyển động cơ bản, rất phù hợp cho những người bận rộn muốn duy trì thói quen vận động.';
	@override String get fb_db_beg_name => 'Toàn Thân - Cơ Bản (Tạ Đơn)';
	@override String get fb_db_int_desc => 'Nâng cao thể lực tổng thể bằng cách gia tăng số hiệp và kết hợp nhiều bài tập tạ đơn đa dạng. Lịch trình này đảm bảo toàn bộ cơ thể được rèn luyện đồng đều, mang lại sự săn chắc, giảm mỡ thừa và cải thiện sức khỏe tim mạch đáng kể.';
	@override String get fb_db_int_name => 'Toàn Thân - Trung Cấp (Tạ Đơn)';
	@override String get fb_gym_adv_desc => 'Đòi hỏi sự bền bỉ đáng kinh ngạc với ba buổi tập cường độ khủng khiếp mỗi tuần. Giáo án này liên tục thử thách khả năng chịu đựng của cả hệ thần kinh lẫn hệ cơ bắp toàn thân, được thiết kế để phá vỡ mọi giới hạn thể chất của người tập lâu năm.';
