			case 'equipment.rope': return 'Dây nhảy';
			case 'exercises.name_arnold_press': return 'Đẩy vai Arnold';
			case 'exercises.desc_arnold_press': return '1. Cầm tạ đơn ở ngang vai, lòng bàn tay hướng vào mặt.\n2. Thở ra và bắt đầu đẩy tạ lên cao qua đầu. Đồng thời từ từ xoay cổ tay sao cho khi tạ lên đỉnh, lòng bàn tay hướng về phía trước.\n3. Hít vào, từ từ hạ tạ xuống và xoay ngược cổ tay trở lại vị trí ban đầu.';
			case 'exercises.name_australian_pull_up': return 'Kéo xà ngang';
			case 'exercises.desc_australian_pull_up': return '1. Gồng chặt cơ mông và bụng để cơ thể tạo thành đường thẳng (như Plank ngửa) dưới thanh xà thấp.\n2. Thở ra, kéo bả vai ra sau và gập khuỷu tay để kéo ngực chạm vào thanh xà.\n3. Giữ đỉnh 1 giây, sau đó hít vào và từ từ hạ thân người xuống thẳng tay.';
			case 'exercises.name_barbell_curl': return 'Cuốn tạ đòn tay trước';
			case 'exercises.desc_barbell_curl': return '1. Giữ lưng thẳng, ngực hơi ưỡn và ép khuỷu tay sát thân người.\n2. Thở ra, siết cơ bắp tay và cuốn tạ đòn lên theo đường vòng cung về phía ngực/cằm.\n3. Hít vào và từ từ hạ thanh tạ đòn xuống vị trí ban đầu với tốc độ chậm để giãn cơ.';
			case 'exercises.name_barbell_row': return 'Gập người kéo tạ đòn';
			case 'exercises.desc_barbell_row': return '1. Cúi người, giữ lưng thẳng tự nhiên, gồng cơ core và mắt nhìn chếch xuống sàn.\n2. Thở ra, siết cơ lưng và kéo thanh tạ hướng thẳng về phía bụng dưới (hoặc rốn).\n3. Giữ hai cùi chỏ sát thân. Ở đỉnh chuyển động, kẹp chặt hai bả vai lại.\n4. Hít vào và hạ tạ xuống từ từ cho đến khi duỗi thẳng tay.';
			case 'exercises.name_barbell_squat': return 'Squat tạ đòn';
			case 'exercises.desc_barbell_squat': return '1. Đặt thanh tạ lên phần cơ cầu vai/lưng trên. Hít sâu xuống bụng (bracing) và gồng cứng cơ core.\n2. Đẩy hông ra sau và gập gối hạ người xuống có kiểm soát. Hạ sâu hết biên độ linh hoạt mà vẫn giữ lưng thẳng.\n3. Đạp mạnh sàn, thở ra dứt khoát và đẩy tạ đi thẳng lên đứng thẳng người.';
			case 'exercises.name_bench_dips': return 'Chống đẩy ngược trên ghế';
			case 'exercises.desc_bench_dips': return '1. Tựa hai tay lên mép ghế, trượt mông ra ngoài. Duỗi thẳng tay để giữ trọng lượng.\n2. Hít vào, từ từ gập khuỷu tay hạ cơ thể xuống cho đến khi cánh tay trên song song với sàn.\n3. Thở ra, dồn lực vào lòng bàn tay dùng cơ tay sau đẩy người lên vị trí ban đầu.';
			case 'exercises.name_bench_press': return 'Đẩy ngực tạ đòn';
			case 'exercises.desc_bench_press': return '1. Nhấc thanh tạ ra khỏi giá đỡ và giữ ngay trên vùng giữa ngực.\n2. Hít vào, kiểm soát và từ từ hạ tạ xuống cho đến khi chạm nhẹ vào giữa ngực. Không thả tạ rơi tự do.\n3. Dừng lại một tíc tắc, sau đó thở ra, đạp mạnh chân xuống sàn và đẩy tạ lên cao theo quỹ đạo hơi chéo về phía đầu.';
			case 'exercises.name_bicycle_crunches': return 'Gập bụng đạp xe';
			case 'exercises.desc_bicycle_crunches': return '1. Nằm ngửa, hai tay đặt sau đầu. Nâng hai chân lên khỏi sàn.\n2. Thở ra, duỗi thẳng chân phải đồng thời vặn thân trên sang trái, đưa khuỷu tay phải hướng về đầu gối trái.\n3. Hít vào khi qua tâm, thở ra và thực hiện đổi bên luân phiên liên tục như đang đạp xe.';
			case 'exercises.name_bulgarian_split_squat': return 'Squat một chân';
			case 'exercises.desc_bulgarian_split_squat': return '1. Đặt mu bàn chân sau lên ghế. Giữ lưng thẳng, ngực ưỡn.\n2. Hít vào, từ từ gập gối hạ thấp hông xuống cho đến khi đùi trước song song với sàn (đầu gối sau gần chạm sàn).\n3. Thở ra, dồn lực vào gót chân trước đẩy người thẳng lên.';
			case 'exercises.name_burpees': return 'Nhảy Burpees';
			case 'exercises.desc_burpees': return '1. Hạ người thành tư thế ngồi xổm, hai tay chống xuống sàn.\n2. Bật nhảy đưa hai chân ra sau vào tư thế Plank cao.\n3. Thực hiện một nhịp hít đất (tùy chọn theo thể lực).\n4. Bật nhảy thu chân về tư thế ngồi xổm, lập tức bật nhảy cao lên không trung và vung tay qua đầu.';
			case 'exercises.name_cable_crossover': return 'Ép ngực chéo với cáp';
			case 'exercises.desc_cable_crossover': return '1. Đứng giữa máy cáp cao. Mở rộng vòng tay, cùi chỏ cong nhẹ cố định.\n2. Thở ra, kéo ép hai tay bắt chéo qua nhau ở phía trước ngực.\n3. Ép chặt cơ ngực 1 giây, hít vào từ từ mở rộng cánh tay.';
			case 'exercises.name_cable_crunch': return 'Gập bụng với cáp';
			case 'exercises.desc_cable_crunch': return '1. Quỳ gối đối diện máy cáp, cầm dây thừng sau gáy. Cố định hoàn toàn hông và đùi.\n2. Thở ra, cuộn tròn cột sống để gập người xuống, hướng khuỷu tay về phía đùi.\n3. Siết chặt cơ bụng ở điểm sâu nhất trong 1 giây.\n4. Hít vào và từ từ nhả cáp về vị trí ban đầu.';
			case 'exercises.name_cable_kickback': return 'Đá mông với cáp';
			case 'exercises.desc_cable_kickback': return '1. Gắn cáp vào cổ chân. Đứng trụ vững, gồng cơ core.\n2. Thở ra, siết cơ mông đá chân ra sau và lên cao theo quỹ đạo vòng cung.\n3. Giữ 1 giây khi cơ mông cuộn lại tối đa.\n4. Hít vào, từ từ kiểm soát cáp để đưa chân về.';
			case 'exercises.name_cable_lateral_raise': return 'Dang vai với cáp';
			case 'exercises.desc_cable_lateral_raise': return '1. Đứng cạnh máy cáp, dùng tay phía ngoài nắm lấy tay cầm ở ròng rọc thấp.\n2. Hơi gập khuỷu tay. Thở ra, nâng tay sang ngang cho đến khi cánh tay song song với sàn.\n3. Giữ lại 1 nhịp ở đỉnh, sau đó hít vào và từ từ hạ xuống có kiểm soát.';
			case 'exercises.name_chest_dips': return 'Xà kép ép ngực';
			case 'exercises.desc_chest_dips': return '1. Trên xà kép, đổ người ngả về phía trước khoảng 30 độ để nhắm vào cơ ngực.\n2. Hít vào, hạ cơ thể cho đến khi vai thấp hơn khuỷu tay (cảm nhận ngực dưới bị kéo căng).\n3. Thở ra, dồn lực lòng bàn tay siết ngực đẩy người lên.';
			case 'exercises.name_chest_supported_row': return 'Nằm ghế dốc kéo lưng';
			case 'exercises.desc_chest_supported_row': return '1. Nằm sấp ngực tựa chắc lên ghế dốc 45 độ. Hai tay buông thõng cầm tạ đơn.\n2. Thở ra, kéo cùi chỏ lên trần nhà ép chặt hai bả vai.\n3. Hít vào từ từ hạ tạ để giãn cơ lưng.';
			case 'exercises.name_chin_up': return 'Hít xà đơn';
			case 'exercises.desc_chin_up': return '1. Nắm thanh xà với lòng bàn tay hướng về phía người. Treo người duỗi thẳng tay.\n2. Thở ra, siết lưng xô và bắp tay kéo người lên cho đến khi cằm vượt qua xà.\n3. Ép chặt hai bả vai. Hít vào và từ từ hạ thân người xuống hết cỡ (dead hang).';
			case 'exercises.name_close_grip_pulldown': return 'Kéo xô hẹp tay';
			case 'exercises.desc_close_grip_pulldown': return '1. Cầm tay cầm V-bar, ngực ưỡn nhẹ.\n2. Thở ra, kéo V-bar hướng xuống phần ngực giữa. Giữ cùi chỏ ép sát vào sườn.\n3. Ép bả vai ở điểm thấp nhất. Hít vào và nhả tạ lên từ từ để kéo giãn cơ xô.';
			case 'exercises.name_crunch': return 'Gập bụng cơ bản';
			case 'exercises.desc_crunch': return '1. Nằm ngửa, gập gối. Hít sâu, siết cơ bụng.\n2. Từ từ cuộn người, nâng đầu và vai rời khỏi sàn. Lưng dưới (thắt lưng) vẫn ép chặt xuống thảm.\n3. Giữ 1 giây, thở ra dứt khoát. Hít vào và hạ người xuống từ từ.';
			case 'exercises.name_crunch_machine': return 'Gập bụng với máy';
			case 'exercises.desc_crunch_machine': return '1. Ngồi cố định vào máy gập bụng. Hít sâu.\n2. Thở ra, cuộn thân trên gập người về trước, co thắt mạnh cơ bụng.\n3. Giữ nguyên 1 giây ở điểm sâu nhất, hít vào nhả máy từ từ.';
			case 'exercises.name_deadlift': return 'Deadlift tạ đòn';
			case 'exercises.desc_deadlift': return '1. Đứng cẳng chân sát thanh đòn. Gập hông cúi xuống, cầm tạ, ưỡn ngực kéo căng cơ xô.\n2. Hít sâu vào bụng. Đạp mạnh chân xuống sàn và đồng thời kéo thân đứng thẳng lên.\n3. Giữ thanh tạ trượt sát đùi. Siết mông ở đỉnh, thở ra.\n4. Đẩy hông ra sau để hạ tạ xuống đất có kiểm soát.';
			case 'exercises.name_decline_bench_press': return 'Đẩy ngực dưới tạ đòn';
			case 'exercises.desc_decline_bench_press': return '1. Nằm trên ghế dốc xuống. Hít sâu, nhấc tạ ra khỏi giá nằm trên vùng ngực dưới.\n2. Hít vào, hạ tạ có kiểm soát chạm nhẹ vào ngực dưới.\n3. Thở ra, dùng lực ngực đẩy tạ lên thẳng vị trí ban đầu.';
			case 'exercises.name_decline_push_up': return 'Hít đất dốc xuống';
			case 'exercises.desc_decline_push_up': return '1. Đặt hai chân lên bục/ghế cao. Cơ thể tạo đường thẳng dốc xuống.\n2. Hít vào, hạ ngực gần chạm sàn. Khuỷu tay gập góc khoảng 45 độ so với thân.\n3. Thở ra, dùng lực ngực trên đẩy người lên thẳng tay.';
			case 'exercises.name_diamond_push_up': return 'Hít đất kim cương';
			case 'exercises.desc_diamond_push_up': return '1. Chống tay tạo hình kim cương (ngón cái và trỏ chạm nhau) ở ngay dưới ngực.\n2. Hít vào, hạ thân người xuống sát mu bàn tay, cùi chỏ ép sát sườn.\n3. Thở ra, siết cơ tay sau đẩy người lên thẳng.';
			case 'exercises.name_dumbbell_bench_press': return 'Đẩy ngực tạ đơn';
			case 'exercises.desc_dumbbell_bench_press': return '1. Nằm ghế bằng, đẩy hai quả tạ thẳng lên trên ngực.\n2. Hít vào, hạ tạ xuống hai bên. Cùi chỏ mở góc khoảng 45-60 độ so với thân người.\n3. Hạ đến khi ngực căng tối đa. Thở ra, siết ngực đẩy tạ vút lên trên.';
			case 'exercises.name_dumbbell_curl': return 'Cuốn tạ đơn tay trước';
			case 'exercises.desc_dumbbell_curl': return '1. Giữ cố định bắp tay (phần từ vai đến khuỷu tay) sát thân người.\n2. Thở ra, cuốn tạ lên về phía vai, xoay ngửa cổ tay.\n3. Siết bắp tay 1 giây ở đỉnh, hít vào hạ tạ có kiểm soát.';
			case 'exercises.name_dumbbell_deadlift': return 'Deadlift tạ đơn';
			case 'exercises.desc_dumbbell_deadlift': return '1. Cầm tạ hai bên hông. Hít sâu, đẩy hông ra sau và chùng gối hạ tạ xuống dọc đùi.\n2. Đạp mạnh hai chân xuống sàn, kéo tạ đứng thẳng lên.\n3. Siết mông ở đỉnh. Thở ra. Đẩy hông ra sau để lặp lại.';
			case 'exercises.name_dumbbell_fly': return 'Ép ngực tạ đơn';
			case 'exercises.desc_dumbbell_fly': return '1. Nằm trên ghế, hai tay cầm tạ đẩy thẳng lên ngực. Hơi gập nhẹ khuỷu tay.\n2. Hít vào, mở rộng cánh tay sang hai bên theo quỹ đạo vòng cung cho đến khi ngực căng tối đa.\n3. Thở ra, ép tạ về lại vị trí ban đầu theo đúng quỹ đạo vòng cung đó.';
			case 'exercises.name_dumbbell_lateral_raise': return 'Dang vai tạ đơn';
			case 'exercises.desc_dumbbell_lateral_raise': return '1. Đứng thẳng, hai tay cầm tạ. Hơi gập nhẹ khuỷu tay.\n2. Thở ra, nâng tạ sang ngang như đang hắt nước, cho đến khi cánh tay song song với sàn.\n3. Hít vào và từ từ hạ tạ xuống không để mất lực căng.';
			case 'exercises.name_dumbbell_lunges': return 'Bước gập gối tạ đơn';
			case 'exercises.desc_dumbbell_lunges': return '1. Cầm tạ hai tay. Hít vào, bước một chân lên phía trước một khoảng vừa đủ.\n2. Hạ thấp hông theo phương thẳng đứng đến khi hai đầu gối đều tạo góc 90 độ.\n3. Thở ra, dồn lực bật mạnh từ chân trước đẩy lùi người về vị trí xuất phát.';
			case 'exercises.name_dumbbell_rdl': return 'Deadlift chân thẳng tạ đơn';
			case 'exercises.desc_dumbbell_rdl': return '1. Đứng thẳng, tạ đơn đặt sát đùi trước. Đầu gối hơi chùng nhẹ.\n2. Hít sâu, đẩy hông thẳng ra phía sau (hip hinge) và trượt tạ dọc xuống chân cho đến khi đùi sau căng.\n3. Thở ra, siết mông đẩy hông về trước để đứng thẳng lên.';
			case 'exercises.name_dumbbell_reverse_fly': return 'Dang vai sau tạ đơn';
			case 'exercises.desc_dumbbell_reverse_fly': return '1. Cúi gập người, lưng thẳng và song song với sàn. Khuỷu tay cong nhẹ.\n2. Thở ra, dang hai cánh tay giương rộng ra hai bên như đôi cánh.\n3. Ép bả vai ở đỉnh, hít vào và từ từ hạ tạ xuống.';
			case 'exercises.name_dumbbell_row': return 'Kéo tạ đơn';
			case 'exercises.desc_dumbbell_row': return '1. Cúi gập người, lưng thẳng. Hai tay cầm tạ buông thõng tự nhiên.\n2. Thở ra, kéo hai quả tạ lên phía mạn sườn, hướng cùi chỏ lên trần nhà.\n3. Ép bả vai ở đỉnh. Hít vào và hạ tạ từ từ xuống.';
			case 'exercises.name_dumbbell_shoulder_press': return 'Đẩy vai tạ đơn';
			case 'exercises.desc_dumbbell_shoulder_press': return '1. Ngồi ưỡn ngực, cầm tạ ngang vai. Thở ra, đẩy tạ thẳng lên đỉnh đầu.\n2. Ép cơ vai ở đỉnh (hai quả tạ gần chạm nhau).\n3. Hít vào và từ từ hạ tạ xuống ngang tai.';
			case 'exercises.name_dumbbell_shrugs': return 'Nhún vai tạ đơn';
			case 'exercises.desc_dumbbell_shrugs': return '1. Hai tay cầm tạ buông thõng hoàn toàn.\n2. Thở ra, nhún hai bờ vai thẳng lên hướng về lỗ tai. Giữ đỉnh 1 giây.\n3. Hít vào, hạ vai xuống sâu để kéo giãn cơ cầu vai.';
			case 'exercises.name_face_pull': return 'Kéo cáp ngang mặt';
			case 'exercises.desc_face_pull': return '1. Lắp dây thừng vào cáp cao. Kéo dây hướng về phía trán.\n2. Tách hai đầu dây ra, xoay cổ tay lên trên và kéo cùi chỏ ra phía sau mang tai.\n3. Ép bả vai 1 giây. Hít vào từ từ nhả tay.';
			case 'exercises.name_glute_bridge': return 'Nâng hông';
			case 'exercises.desc_glute_bridge': return '1. Nằm ngửa, gập gối. Hít sâu, gồng cơ bụng.\n2. Thở ra, dồn lực gót chân siết mông đẩy hông lên tạo đường thẳng từ gối đến vai.\n3. Giữ 1-2 giây ở đỉnh. Hít vào từ từ hạ hông xuống sàn.';
			case 'exercises.name_goblet_squat': return 'Squat ôm tạ';
			case 'exercises.desc_goblet_squat': return '1. Ôm dọc 1 quả tạ đơn sát trước ngực. Hít sâu, gồng cơ core.\n2. Đẩy hông ra sau và hạ người tư thế Squat. Hai cùi chỏ đi vào giữa hai đầu gối.\n3. Thở ra, dồn lực gót chân đứng thẳng dậy.';
			case 'exercises.name_hack_squat': return 'Hack Squat';
			case 'exercises.desc_hack_squat': return '1. Áp sát lưng phẳng vào đệm máy Hack Squat. Hít vào, gập gối hạ người.\n2. Xuống đến khi đùi song song với bàn đạp.\n3. Thở ra, dồn lực gót chân đẩy máy vút lên vị trí cũ.';
			case 'exercises.name_hammer_curl': return 'Cuốn tạ búa';
			case 'exercises.desc_hammer_curl': return '1. Hai tay cầm tạ đơn, lòng bàn tay luôn hướng vào nhau. Cố định bắp tay sát sườn.\n2. Thở ra, cuốn tạ lên vai, giữ nguyên mặt phẳng tay (như đang đóng búa).\n3. Hít vào từ từ hạ tạ xuống.';
			case 'exercises.name_hanging_leg_raise': return 'Treo người nâng chân';
			case 'exercises.desc_hanging_leg_raise': return '1. Treo người trên xà. Siết chặt cơ core.\n2. Thở ra, nâng hai chân lên phía trước cho đến khi song song với sàn (hoặc cao hơn).\n3. Giữ 1 giây, hít vào và từ từ hạ chân có kiểm soát.';
			case 'exercises.name_high_knees': return 'Chạy nâng cao đùi';
			case 'exercises.desc_high_knees': return '1. Chạy tại chỗ, kéo cao một bên đầu gối ngang hông.\n2. Luân phiên đánh gối nhanh nhất có thể.\n3. Đánh tay nhịp nhàng như đang chạy nước rút.';
			case 'exercises.name_hip_abduction': return 'Máy đẩy đùi ngoài';
			case 'exercises.desc_hip_abduction': return '1. Ngồi máy đẩy đùi ngoài, hai chân khép lại tựa vào đệm.\n2. Thở ra, dùng lực mông ngoài đẩy đùi mở rộng sang hai bên hết cỡ.\n3. Giữ siết cơ mông 1 giây, hít vào từ từ khép lại.';
			case 'exercises.name_hip_adduction': return 'Máy ép đùi trong';
			case 'exercises.desc_hip_adduction': return '1. Ngồi máy ép đùi trong, mở rộng hai chân tựa vào đệm tì.\n2. Thở ra, dùng lực đùi trong ép hai chân sát lại với nhau.\n3. Giữ 1 giây. Hít vào từ từ nhả tạ mở chân ra.';
			case 'exercises.name_hip_thrust': return 'Nâng hông tạ đòn';
			case 'exercises.desc_hip_thrust': return '1. Tựa vai lên ghế, đặt thanh tạ ngang hông. Căn chỉnh sao cho khi đẩy hông lên đỉnh, cẳng chân vuông góc với mặt sàn.\n2. Hít vào, gồng cơ core, cằm hơi thu về phía ngực.\n3. Thở ra, dồn lực vào gót chân và siết cơ mông đẩy tạ lên cho đến khi đùi và thân trên song song với sàn.\n4. Giữ 1-2 giây, sau đó từ từ hạ hông xuống.';
			case 'exercises.name_hyperextensions': return 'Gập lưng dưới';
			case 'exercises.desc_hyperextensions': return '1. Tựa hông vào ghế. Hít vào, gập người xuống vuông góc.\n2. Thở ra, dùng cơ lưng dưới và mông kéo thân người lên tạo thành đường thẳng.\n3. Giữ đỉnh 1 giây, hít vào hạ thân người chậm rãi.';
			case 'exercises.name_incline_barbell_press': return 'Đẩy ngực trên tạ đòn';
			case 'exercises.desc_incline_barbell_press': return '1. Nằm ghế dốc lên (30-45 độ). Nhấc tạ đòn nằm trên vùng ngực trên (xương quai xanh).\n2. Hít vào, hạ tạ chạm nhẹ ngực trên có kiểm soát.\n3. Thở ra, đẩy thẳng tạ lên vị trí ban đầu.';
			case 'exercises.name_incline_dumbbell_fly': return 'Ép ngực trên tạ đơn';
			case 'exercises.desc_incline_dumbbell_fly': return '1. Nằm ghế dốc lên. Đẩy 2 tạ đơn thẳng lên trần. Hơi gập khuỷu tay.\n2. Hít vào, mở rộng cánh tay sang hai bên cho đến khi ngực trên căng tối đa.\n3. Thở ra, ép ngực đưa tạ về vị trí ban đầu.';
			case 'exercises.name_incline_dumbbell_press': return 'Đẩy ngực trên tạ đơn';
			case 'exercises.desc_incline_dumbbell_press': return '1. Nằm ghế dốc lên, đẩy 2 tạ đơn lên thẳng vùng ngực trên.\n2. Hít vào, hạ tạ xuống hai bên. Cùi chỏ mở góc khoảng 45 độ.\n3. Thở ra, siết ngực trên đẩy tạ vút lên, hai tạ gần chạm nhau ở đỉnh.';
			case 'exercises.name_incline_push_up': return 'Hít đất dốc lên';
			case 'exercises.desc_incline_push_up': return '1. Chống hai tay lên bục/ghế cao. Lưng, hông, chân tạo thành một đường thẳng.\n2. Hít vào, gập cùi chỏ hạ ngực gần chạm mép bục.\n3. Thở ra, đẩy mạnh người lên thẳng tay.';
			case 'exercises.name_indoor_cycling': return 'Đạp xe trong nhà';
			case 'exercises.desc_indoor_cycling': return '1. Bắt đầu đạp tốc độ vừa phải để làm nóng khớp.\n2. Gồng nhẹ cơ bụng giữ ổn định thân trên, duy trì vòng đạp mượt mà, tròn vành.\n3. Điều chỉnh lực cản (resistance) theo giáo án tập luyện.';
			case 'exercises.name_jump_rope': return 'Nhảy dây';
			case 'exercises.desc_jump_rope': return '1. Dùng lực cổ tay xoay dây vòng qua đầu.\n2. Bật nhảy nhẹ nhàng bằng mũi chân vừa đủ để dây đi qua.\n3. Duy trì nhịp điệu liên tục và hít thở đều.';
			case 'exercises.name_jumping_jacks': return 'Nhảy bật vung tay';
			case 'exercises.desc_jumping_jacks': return '1. Bật nhảy dang hai chân rộng hơn vai.\n2. Đồng thời vung hai tay vòng qua đỉnh đầu.\n3. Bật nhảy thu chân và tay về vị trí cũ một cách liên tục.';
			case 'exercises.name_lat_pulldown': return 'Kéo xô với máy';
			case 'exercises.desc_lat_pulldown': return '1. Ngồi vào máy cáp, ngả người ra sau khoảng 10 độ, ưỡn ngực.\n2. Thở ra, gồng cơ xô kéo cùi chỏ hướng xuống thảm và ép ra sau.\n3. Thanh xà chạm ngực trên, hít vào nhả cáp từ từ lên tận cùng để giãn cơ xô.';
			case 'exercises.name_leg_extension': return 'Đá đùi trước';
			case 'exercises.desc_leg_extension': return '1. Ngồi ép sát toàn bộ lưng và mông vào ghế máy.\n2. Thở ra, dùng cơ đùi trước đá tạ lên tới khi hai chân duỗi thẳng.\n3. Giữ 1-2 giây siết đùi. Hít vào từ từ hạ tạ.';
			case 'exercises.name_leg_press': return 'Đạp đùi';
			case 'exercises.desc_leg_press': return '1. Ngồi máy đạp đùi, chân đặt trên bàn đạp. Hít vào, gập gối hạ tạ về phía ngực.\n2. Hạ tới khi đùi và cẳng chân vuông góc (90 độ).\n3. Thở ra, dồn lực gót chân đẩy bàn đạp vút lên vị trí ban đầu.';
			case 'exercises.name_low_to_high_fly': return 'Ép ngực dưới với cáp';
			case 'exercises.desc_low_to_high_fly': return '1. Đứng giữa máy cáp cao. Mở rộng vòng tay, cùi chỏ cong nhẹ.\n2. Thở ra, kéo hai tay ép chéo đi xuống dưới hướng về phía bụng/hông.\n3. Ép ngực 1 giây ở điểm cuối, hít vào mở tay từ từ lên.';
			case 'exercises.name_lying_leg_curl': return 'Nằm móc đùi sau';
			case 'exercises.desc_lying_leg_curl': return '1. Nằm sấp, ép chặt phần hông xuống nệm máy.\n2. Thở ra, dùng cơ đùi sau cuộn đệm tạ về phía mông hết mức có thể.\n3. Giữ đỉnh 1 giây. Hít vào nhả tạ chậm rãi, không để các phiến tạ chạm nhau.';
			case 'exercises.name_lying_leg_raise': return 'Nằm nâng chân';
			case 'exercises.desc_lying_leg_raise': return '1. Nằm ngửa, thắt lưng ép chặt xuống sàn.\n2. Thở ra, nâng cả hai chân lên vuông góc với sàn.\n3. Hít vào, từ từ hạ chân xuống cách sàn 5-10cm (không chạm đất) và lặp lại.';
			case 'exercises.name_machine_chest_press': return 'Đẩy ngực với máy';
			case 'exercises.desc_machine_chest_press': return '1. Ngồi vào máy đẩy ngực, hai tay nắm chắc tay cầm.\n2. Thở ra, dùng cơ ngực đẩy mạnh tay cầm về phía trước.\n3. Hít vào, nhả tạ lùi về vị trí ngực giãn có kiểm soát.';
			case 'exercises.name_mountain_climbers': return 'Leo núi';
			case 'exercises.desc_mountain_climbers': return '1. Chống đẩy ở tư thế Plank cao.\n2. Rút nhanh luân phiên từng đầu gối hướng về phía ngực.\n3. Giữ cơ core ổn định, không để hông nảy lên xuống quá nhiều.';
			case 'exercises.name_one_arm_row': return 'Kéo tạ đơn một tay';
			case 'exercises.desc_one_arm_row': return '1. Chống 1 gối và 1 tay lên ghế, tay kia cầm tạ buông thõng tự nhiên.\n2. Thở ra, kéo cùi chỏ lên cao qua lưng, ép sát mạn sườn.\n3. Hít vào, hạ tạ chậm để giãn hết biên độ bả vai.';
			case 'exercises.name_overhead_cable_triceps': return 'Duỗi tay sau qua đầu bằng dây cáp';
			case 'exercises.desc_overhead_cable_triceps': return '1. Gắn dây thừng vào ròng rọc thấp của máy cáp. Đứng quay lưng lại với máy, cầm dây bằng cả hai tay và kéo qua đầu sao cho dây nằm sau gáy, cùi chỏ hướng lên.\n2. Thở ra, duỗi thẳng hai tay lên trên cao, giữ cùi chỏ cố định sát đầu.\n3. Hít vào, từ từ hạ dây thừng về vị trí ban đầu sau gáy có kiểm soát.';
			case 'exercises.name_overhead_press': return 'Đẩy vai tạ đòn qua đầu';
			case 'exercises.desc_overhead_press': return '1. Hít sâu, gồng chặt cơ bụng và mông.\n2. Thở ra, đẩy mạnh thanh đòn thẳng lên trần nhà. Khi thanh đòn vừa qua mặt, hơi đẩy đầu về phía trước để thanh đòn nằm ngay trên đỉnh đầu.\n3. Hít vào và từ từ hạ thanh đòn về lại vai trước.';
			case 'exercises.name_overhead_triceps_extension': return 'Duỗi tay sau qua đầu';
			case 'exercises.desc_overhead_triceps_extension': return '1. Cầm 1 tạ đơn đưa qua đầu. Cố định phần bắp tay ép sát mang tai.\n2. Hít vào, gập khuỷu tay hạ tạ xuống gáy cho đến khi cơ tay sau căng.\n3. Thở ra, duỗi khuỷu tay đẩy quả tạ lên thẳng vị trí ban đầu.';
			case 'exercises.name_pec_deck_fly': return 'Ép ngực với máy';
			case 'exercises.desc_pec_deck_fly': return '1. Ngồi máy Pec Deck, tay ngang ngực. Hít vào mở rộng tay về phía sau để giãn ngực.\n2. Thở ra, kéo hai tay cầm ép sát vào nhau ở ngay trước ngực.\n3. Siết chặt ngực 1 giây, hít vào nhả tay chậm rãi.';
			case 'exercises.name_pike_push_up': return 'Hít đất chúi đầu';
			case 'exercises.desc_pike_push_up': return '1. Vào tư thế chữ V ngược (hông nhô cao lên trần).\n2. Hít vào, hạ đỉnh đầu xuống gần chạm sàn, tạo hình tam giác với 2 bàn tay.\n3. Thở ra, đẩy mạnh người về tư thế ban đầu.';
			case 'exercises.name_plank': return 'Plank';
			case 'exercises.desc_plank': return '1. Chống hai cùi chỏ xuống sàn. Cơ thể thẳng tắp từ gót chân tới đầu.\n2. Chủ động siết cơ bụng, gồng cơ mông và đùi trước.\n3. Giữ tư thế tĩnh và duy trì nhịp thở đều đặn.';
			case 'exercises.name_preacher_curl': return 'Cuốn tay trước trên ghế tựa';
			case 'exercises.desc_preacher_curl': return '1. Ngồi ghế Preacher, khóa chặt bắp tay trên mặt đệm. Cầm tạ đòn ngửa tay.\n2. Thở ra, cuốn tạ về phía vai, siết chặt bắp tay.\n3. Hít vào, hạ tạ chậm đến khi tay gần duỗi thẳng.';
			case 'exercises.name_pull_up': return 'Hít xà đơn';
			case 'exercises.desc_pull_up': return '1. Nắm thanh xà lòng bàn tay hướng tới trước. Gồng cơ core chống đung đưa.\n2. Thở ra, kéo cùi chỏ hướng xuống để nâng người qua xà.\n3. Hít vào, từ từ hạ người xuống đến khi duỗi thẳng tay.';
			case 'exercises.name_push_up': return 'Hít đất';
			case 'exercises.desc_push_up': return '1. Nằm sấp chống thẳng tay. Lưng, hông, chân tạo đường thẳng.\n2. Hít vào, gập cùi chỏ hạ ngực cách sàn khoảng 1-2cm.\n3. Thở ra, đẩy ngực và tay sau vươn người lên vị trí ban đầu.';
			case 'exercises.name_reverse_pec_deck': return 'Ép vai sau với máy';
			case 'exercises.desc_reverse_pec_deck': return '1. Ngồi quay mặt vào máy Pec Deck. Cầm tay nắm, cùi chỏ hơi cong nhẹ.\n2. Thở ra, siết vai sau kéo hai tay giang rộng ra phía sau lưng.\n3. Ép chặt hai bả vai ở đỉnh, hít vào từ từ khép tay lại.';
			case 'exercises.name_romanian_deadlift': return 'Deadlift chân thẳng tạ đòn';
			case 'exercises.desc_romanian_deadlift': return '1. Cầm thanh tạ sát đùi, đầu gối chùng nhẹ. Ưỡn ngực.\n2. Hít vào, đẩy hông thẳng ra sau (hip hinge), trượt tạ dọc chân tới khi đùi sau căng hết cỡ.\n3. Thở ra, siết mông đẩy hông về trước để đứng thẳng.';
			case 'exercises.name_russian_twist': return 'Ngồi xoay eo kiểu Nga';
			case 'exercises.desc_russian_twist': return '1. Ngồi ngả người ra sau hình chữ V, nhấc gót chân khỏi sàn.\n2. Thở ra, xoay mạnh thân trên (có hoặc không tạ) sang phải.\n3. Hít vào qua tâm, thở ra tiếp tục xoay sang trái luân phiên.';
			case 'exercises.name_seated_cable_row_vgrip': return 'Ngồi Kéo Cáp Hẹp Tay';
			case 'exercises.desc_seated_cable_row_vgrip': return '1. Ngồi vào máy, đặt hai chân lên bục, gối hơi cong và hai tay nắm lấy tay cầm chữ V.\n2. Giữ lưng thẳng, ưỡn ngực, thở ra và kéo tay cầm về phía rốn, đảm bảo ép sát hai cùi chỏ vào mạn sườn.\n3. Siết chặt cơ lưng giữa ở nhịp kéo, hít vào và từ từ duỗi tay về vị trí ban đầu để cảm nhận lực giãn ở cơ xô.';
			case 'exercises.name_seated_cable_row_widegrip': return 'Ngồi Kéo Cáp Rộng Tay';
			case 'exercises.desc_seated_cable_row_widegrip': return '1. Ngồi vào máy, hai tay nắm lấy thanh đòn rộng (lòng bàn tay úp xuống), khoảng cách hai tay rộng hơn vai.\n2. Giữ lưng thẳng, thở ra và kéo thanh đòn về phía ngực dưới, hai cùi chỏ hơi dang rộng ra hai bên.\n3. Siết chặt bả vai để tập trung vào cơ lưng trên và vai sau, hít vào và từ từ duỗi tay về vị trí ban đầu.';
			case 'exercises.name_seated_calf_raise': return 'Ngồi nhón gót';
			case 'exercises.desc_seated_calf_raise': return '1. Ngồi máy nhón gót, đặt đệm tì lên đùi dưới.\n2. Hít vào, hạ gót chân xuống thấp nhất để kéo giãn cơ bắp chân.\n3. Thở ra, dùng mũi chân nhón gót lên cao nhất có thể. Giữ đỉnh 1 giây.';
			case 'exercises.name_seated_incline_curl': return 'Cuốn tay trước ghế dốc';
			case 'exercises.desc_seated_incline_curl': return '1. Ngồi ghế dốc 45-60 độ, hai tay cầm tạ đơn buông thõng duỗi thẳng ra sau thân người.\n2. Cố định bắp tay, thở ra cuốn tạ lên phía vai, xoay ngửa lòng bàn tay.\n3. Hít vào từ từ hạ tạ xuống hoàn toàn để giãn bắp tay.';
			case 'exercises.name_seated_leg_curl': return 'Ngồi móc đùi sau';
			case 'exercises.desc_seated_leg_curl': return '1. Ngồi máy móc đùi sau, đệm tì khóa ngay trên gót chân (cổ chân).\n2. Thở ra, cuộn hai chân gập xuống gầm ghế hết mức.\n3. Hít vào, nhả tạ chậm lên trên không để chạm các phiến tạ khác.';
			case 'exercises.name_seated_wrist_curl': return 'Ngồi gập cổ tay';
			case 'exercises.desc_seated_wrist_curl': return '1. Ngồi tựa cẳng tay lên đùi, lòng bàn tay ngửa cầm tạ.\n2. Nhả tạ trượt dần xuống các đốt ngón tay để giãn cẳng tay. Thở ra, gập mạnh cổ tay cuộn tạ lên.\n3. Hít vào nhả tạ chậm rãi.';
			case 'exercises.name_shoulder_press_machine': return 'Đẩy vai với máy';
			case 'exercises.desc_shoulder_press_machine': return '1. Ngồi máy đẩy vai, nắm chắc tay cầm ngang tầm vai.\n2. Thở ra, đẩy vút tạ thẳng lên trên đầu (nhưng không khóa chặt khớp cùi chỏ).\n3. Hít vào, kiểm soát hạ tạ xuống nhẹ nhàng về vị trí ban đầu.';
			case 'exercises.name_single_arm_lat_pulldown': return 'Kéo xô cáp một tay';
			case 'exercises.desc_single_arm_lat_pulldown': return '1. Ngồi máy cáp cao, một tay cầm tay nắm chữ D. Ưỡn ngực.\n2. Thở ra, kéo cùi chỏ nhắm thẳng xuống mạn sườn.\n3. Siết cơ xô ở điểm cuối 1 giây, hít vào nhả cáp từ từ.';
			case 'exercises.name_skull_crushers': return 'Nằm duỗi tay sau tạ đòn';
			case 'exercises.desc_skull_crushers': return '1. Nằm ghế bằng, cầm tạ đòn đẩy lên. Nghiêng bắp tay về phía đầu khoảng 15 độ.\n2. Hít vào, gập cùi chỏ hạ tạ hướng về đỉnh đầu/trán.\n3. Thở ra, duỗi mạnh khuỷu tay đẩy tạ lên lại.';
			case 'exercises.name_smith_machine_squat': return 'Squat máy Smith';
			case 'exercises.desc_smith_machine_squat': return '1. Đặt tạ máy Smith lên vai, đứng bước hai chân hơi tiến về phía trước một chút so với thanh đòn.\n2. Hít vào, đẩy hông hạ người xuống tư thế squat song song.\n3. Thở ra dồn lực gót chân đẩy người thẳng lên.';
			case 'exercises.name_squat': return 'Squat cơ bản';
			case 'exercises.desc_squat': return '1. Hít sâu, gồng cơ bụng. Đẩy hông ra sau và gập đầu gối như đang ngồi xuống một chiếc ghế vô hình.\n2. Hạ người xuống cho đến khi nếp gấp hông nằm thấp hơn đỉnh đầu gối (nếu độ dẻo dai cho phép). Trọng lượng dồn đều lên toàn bộ bàn chân.\n3. Thở ra, đạp mạnh bàn chân xuống sàn, siết cơ mông và đùi đẩy người đứng thẳng dậy.';
			case 'exercises.name_stair_climber': return 'Leo cầu thang bằng máy';
			case 'exercises.desc_stair_climber': return '1. Bước nhịp nhàng lên các bậc thang của máy.\n2. Đặt toàn bộ bàn chân lên bậc, tập trung dồn lực đạp từ gót chân để ép cơ mông làm việc.';
			case 'exercises.name_standing_calf_raise': return 'Đứng nhón gót';
			case 'exercises.desc_standing_calf_raise': return '1. Đứng nửa bàn chân trên bục. Hít vào hạ gót chân xuống sâu nhất mặt bục.\n2. Thở ra, nhón gót lên cao hết cỡ. Đầu gối thẳng nhưng không khóa khớp.\n3. Giữ căng ở đỉnh 1-2 giây rồi từ từ hạ xuống.';
			case 'exercises.name_superman': return 'Nằm sấp nâng tay chân';
			case 'exercises.desc_superman': return '1. Nằm sấp, duỗi thẳng tay và chân.\n2. Siết lưng dưới, đồng thời nâng tay, ngực và chân rời khỏi thảm uốn cong người.\n3. Giữ 2-3 giây ở đỉnh, hít thở nông rồi từ từ hạ xuống.';
			case 'exercises.name_t_bar_row': return 'Kéo tạ chữ T';
			case 'exercises.desc_t_bar_row': return '1. Đứng khom người, hai tay cầm thanh T-Bar. Lưng thẳng tự nhiên.\n2. Thở ra, kéo mạnh thanh tạ hướng về bụng, ép hai bả vai sát nhau.\n3. Hít vào, hạ thanh tạ có kiểm soát để kéo giãn cơ lưng.';
			case 'exercises.name_treadmill': return 'Chạy bộ trên máy';
			case 'exercises.desc_treadmill': return '1. Khởi động băng chạy ở tốc độ chậm rồi mới bước vào.\n2. Điều chỉnh Tốc độ (Speed) và Độ dốc (Incline) theo mục tiêu giáo án.\n3. Giữ người thẳng, mắt nhìn trước, đánh tay nhịp nhàng.';
			case 'exercises.name_tricep_pushdown': return 'Kéo cáp tay sau';
			case 'exercises.desc_tricep_pushdown': return '1. Đứng ở máy cáp cao. Cố định cùi chỏ ép chặt mạn sườn.\n2. Thở ra, đẩy cáp thẳng xuống đất đến khi cánh tay duỗi thẳng.\n3. Hít vào, nhả cáp từ từ đi lên, không vung vẩy cùi chỏ.';
			case 'exercises.name_upright_row': return 'Kéo tạ đòn thẳng đứng';
			case 'exercises.desc_upright_row': return '1. Cầm thanh tạ đòn ép sát đùi.\n2. Thở ra, dùng cùi chỏ kéo tạ thẳng đứng lên vùng cằm. Cùi chỏ luôn phải cao hơn cổ tay.\n3. Giữ đỉnh 1 giây, hít vào hạ tạ xuống thẳng đứng.';
			case 'exercises.desc_warm_up': return 'Xoay kỹ các khớp: cổ tay, cổ chân, vai, hông và gối trong 5-10 phút để làm trơn khớp và tăng nhịp tim.';
			case 'exercises.type_cardio_dist': return 'Khoảng cách & Thời gian';
			case 'exercises.type_cardio_steps': return 'Bước chân & Thời gian';
