			case 'programs.combo_db_int_name': return 'Đẩy Kéo Chân & Trên Dưới - Trung Cấp (Tạ Đơn)';
			case 'programs.combo_gym_adv_desc': return 'Đỉnh cao của nghệ thuật lập trình tập luyện với năm buổi cường độ gắt gao nhất. Giáo án này được thiết kế riêng cho những cá nhân đã dày dặn kinh nghiệm, muốn áp đặt cơ thể vào trạng thái căng thẳng liên tục để đạt được sự hoàn mỹ về vóc dáng.';
			case 'programs.combo_gym_adv_name': return 'Đẩy Kéo Chân & Trên Dưới - Nâng Cao (Phòng Tập)';
			case 'programs.combo_gym_beg_desc': return 'Tạo bước đệm chuyển tiếp nhẹ nhàng với ba ngày mỗi tuần để cơ thể dần làm quen trước khi tiến tới lịch tập kết hợp năm ngày chuyên sâu. Giúp xây dựng nền móng vững chắc và chuẩn bị thể lực cho những thử thách khắc nghiệt hơn.';
			case 'programs.combo_gym_beg_name': return 'Đẩy Kéo Chân & Trên Dưới - Cơ Bản (Phòng Tập)';
			case 'programs.combo_gym_int_desc': return 'Cấu trúc năm buổi mỗi tuần mang đến sự cân bằng hoàn hảo giữa mục tiêu phát triển độ lớn cơ bắp và gia tăng sức mạnh tối đa. Sự luân phiên thông minh giữa các ngày tập giúp tối ưu hóa khả năng phục hồi và ngăn ngừa tình trạng quá tải.';
			case 'programs.combo_gym_int_name': return 'Đẩy Kéo Chân & Trên Dưới - Trung Cấp (Phòng Tập)';
			case 'programs.fb_bw_adv_desc': return 'Hành trình rèn luyện sức mạnh nguyên thủy thông qua các động tác nâng cao như hít xà đơn, xà kép và các biến thể khó kiểm soát. Đòi hỏi sự kết hợp hoàn hảo giữa sức mạnh thuần túy, sự thăng bằng và sức mạnh hệ cơ lõi tuyệt đối.';
			case 'programs.fb_bw_adv_name': return 'Toàn Thân - Nâng Cao (Không Tạ)';
			case 'programs.fb_bw_beg_desc': return 'Sử dụng chính trọng lượng cơ thể làm sức cản để rèn luyện thăng bằng và củng cố sức mạnh vùng cơ lõi. Lịch trình nhẹ nhàng, dễ tiếp cận ở mọi không gian, giúp bạn hình thành thói quen kỷ luật mà không cần đầu tư bất kỳ dụng cụ phức tạp nào.';
			case 'programs.fb_bw_beg_name': return 'Toàn Thân - Cơ Bản (Không Tạ)';
			case 'programs.fb_bw_int_desc': return 'Đẩy mạnh mức độ thử thách thông qua các bài tập thể dục trọng lượng cơ thể biến thể phức tạp hơn. Giáo án này không chỉ đốt cháy năng lượng mạnh mẽ mà còn phát triển sự dẻo dai, linh hoạt và khả năng kiểm soát cơ thể trong không gian.';
			case 'programs.fb_bw_int_name': return 'Toàn Thân - Trung Cấp (Không Tạ)';
			case 'programs.fb_db_adv_desc': return 'Vắt kiệt sức lực toàn thân bằng các kỹ thuật kiểm soát nhịp độ chậm rãi và cường độ tập luyện đỉnh cao cùng tạ đơn. Giáo án ép buộc mọi sợi cơ phải tham gia vào quá trình vận động, đem lại hiệu quả tăng cơ và cắt nét vượt xa mong đợi.';
			case 'programs.fb_db_adv_name': return 'Toàn Thân - Nâng Cao (Tạ Đơn)';
			case 'programs.fb_db_beg_desc': return 'Giải pháp tập luyện toàn diện tại nhà cực kỳ tiết kiệm thời gian chỉ với một đôi tạ đơn. Giáo án giúp đánh thức mọi nhóm cơ trên cơ thể thông qua các chuyển động cơ bản, rất phù hợp cho những người bận rộn muốn duy trì thói quen vận động.';
			case 'programs.fb_db_beg_name': return 'Toàn Thân - Cơ Bản (Tạ Đơn)';
			case 'programs.fb_db_int_desc': return 'Nâng cao thể lực tổng thể bằng cách gia tăng số hiệp và kết hợp nhiều bài tập tạ đơn đa dạng. Lịch trình này đảm bảo toàn bộ cơ thể được rèn luyện đồng đều, mang lại sự săn chắc, giảm mỡ thừa và cải thiện sức khỏe tim mạch đáng kể.';
			case 'programs.fb_db_int_name': return 'Toàn Thân - Trung Cấp (Tạ Đơn)';
			case 'programs.fb_gym_adv_desc': return 'Đòi hỏi sự bền bỉ đáng kinh ngạc với ba buổi tập cường độ khủng khiếp mỗi tuần. Giáo án này liên tục thử thách khả năng chịu đựng của cả hệ thần kinh lẫn hệ cơ bắp toàn thân, được thiết kế để phá vỡ mọi giới hạn thể chất của người tập lâu năm.';
			case 'programs.fb_gym_adv_name': return 'Toàn Thân - Nâng Cao (Phòng Tập)';
			case 'programs.fb_gym_beg_desc': return 'Kích hoạt toàn bộ các nhóm cơ chính trên cơ thể chỉ trong một buổi tập với tần suất hai đến ba lần mỗi tuần. Đây là bước đệm hoàn hảo giúp người mới làm quen với sự kháng lực của tạ, tối ưu hóa thời gian và làm quen với kỹ thuật chuyển động cơ bản.';
			case 'programs.fb_gym_beg_name': return 'Toàn Thân - Cơ Bản (Phòng Tập)';
			case 'programs.fb_gym_int_desc': return 'Lịch tập ba buổi mỗi tuần lấy cảm hứng từ các vận động viên sức mạnh chuyên nghiệp. Tập trung chủ yếu vào các bài tập tạ đòn hạng nặng để kích hoạt hệ thần kinh trung ương, từ đó mang lại sức mạnh nền tảng vượt trội và khối lượng cơ bắp dày dặn.';
