			case 'workout.title_warn_muscle_zone_green': return 'Màu Xanh (Sẵn sàng)';
			case 'workout.desc_warn_muscle_zone_green': return 'Đã phục hồi sinh lý. Bạn có thể tự tự tin tập luyện với cường độ tối đa.';
			case 'workout.title_warn_muscle_zone_red': return 'Màu Đỏ (Nguy hiểm)';
			case 'workout.desc_warn_muscle_zone_red': return 'Cơ bắp đang quá tải! Cần nghỉ ngơi thêm để tránh đứt rách sợi cơ.';
			case 'workout.title_warn_muscle_zone_yellow': return 'Màu Vàng (Đang hồi phục)';
			case 'workout.desc_warn_muscle_zone_yellow': return 'Cơ bắp vẫn còn hơi mỏi. Nếu bắt buộc tập, hãy chọn cường độ vừa phải.';
			case 'workout.msg_warn_no_data': return 'Chưa có đủ dữ liệu để đánh giá.';
			case 'workout.msg_warn_recovery_achieved': return ({required Object arg1}) => 'Đã hồi phục ${arg1}%!';
			case 'workout.fmt_warn_recovery_percent': return ({required Object arg1}) => '${arg1}%';
			case 'workout.fmt_warn_recovery_time_remaining': return ({required Object arg1, required Object arg2, required Object arg3}) => 'Để đạt ${arg1}% cần nghỉ thêm ${arg2}g ${arg3}p';
			case 'workout.msg_warn_safe': return 'Mức tạ an toàn.';
			case 'workout.status_working': return 'Đang tập';
			case 'workout.status_workout_done': return 'Đã hoàn thành buổi tập';
			case 'workout.lbl_workout_in_progress': return 'Đang tập luyện...';
			case 'workout.col_workout_name': return 'Tên buổi tập';
			default: return null;
		}
	}
}
